<script setup lang="ts">
import { label } from '../blog/siteText'
import { ref,watch,computed } from 'vue'
import PhotoGallery from './PhotoGallery.vue'
const props=defineProps<{data:any;annual:boolean;year:string;typeId:string;page:number}>(),emit=defineEmits<{(e:'navigate',path:string):void}>()
const chosenYear=ref(props.year),type=ref(props.typeId)
watch(()=>[props.year,props.typeId],()=>{chosenYear.value=props.year;type.value=props.typeId})
const years=computed(()=>[...new Set([...(props.data.years||[]),new Date().getFullYear(),...(props.year?[Number(props.year)]:[])])].sort((a,b)=>b-a))
function path(page=1){const q=new URLSearchParams({page:String(page)});if(type.value)q.set('type_id',type.value);if(!props.annual&&chosenYear.value)q.set('year',chosenYear.value);return (props.annual?'/year-review/'+(chosenYear.value||new Date().getFullYear()):'/timeline')+'?'+q}
</script>
<template><section class="life-feed"><header class="section-heading"><span class="blog-kicker">{{annual?'A YEAR, WELL REMEMBERED':'CHAPTERS THROUGH TIME'}}</span><h1>{{annual?year+' · '+label('page.year','年度回顾'):label('page.timeline','生活时间线')}}</h1><p>将旅行、礼物、影像和重要片刻，按生活自己的节奏收藏。这里只展示已发布的私人记录。</p></header><form class="life-filters" @submit.prevent="emit('navigate',path())"><label>年份<select v-model="chosenYear" aria-label="年份"><option v-if="!annual" value="">全部年份</option><option v-for="y in years" :key="y" :value="String(y)">{{y}} 年</option></select></label><label>内容类型<select v-model="type" aria-label="内容类型"><option value="">全部类型</option><option v-for="t in data.types" :key="t.id" :value="t.id">{{t.name}}</option></select></label><button class="blog-primary">筛选生活记录</button><a v-if="!annual&&chosenYear" :href="'/year-review/'+chosenYear" @click.prevent="emit('navigate','/year-review/'+chosenYear)">查看这一年 ↗</a></form>
<section v-if="annual" class="year-summary"><h2>这一年的收藏</h2><p>{{data.total}} 篇记录 · {{data.photos.length}} 张精选影像</p><ul><li v-for="c in data.counts" :key="c.type_id||c.name">{{c.name}} · {{c.count}}</li></ul><PhotoGallery :photos="data.photos" layout="masonry"/><div class="year-photo-links"><p v-for="p in data.photos" :key="p.id"><span>{{p.caption||'精选影像'}}</span><a v-for="r in p.records" :key="r.id" :href="'/posts/'+r.id" @click.prevent="emit('navigate','/posts/'+r.id)">{{r.title}} ↗</a></p></div></section>
<h2 v-if="annual">生活记录</h2><ol v-if="data.items.length" class="life-records"><li v-for="r in data.items" :key="r.id"><time>{{r.display_date}}</time><a :href="'/posts/'+r.id" @click.prevent="emit('navigate','/posts/'+r.id)"><span class="blog-tag">{{r.record_mode_name||r.type_name}}</span><h2>{{r.title}}</h2></a><p>{{r.excerpt.replace(/<[^>]*>/g,'').slice(0,160)}}</p></li></ol><p v-else class="blog-empty">这一页还没有已发布的生活记录。</p><nav class="blog-pagination" aria-label="生活记录分页"><button :disabled="page<=1" @click="emit('navigate',path(page-1))">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(data.total/20))}}</span><button :disabled="page*20>=data.total" @click="emit('navigate',path(page+1))">下一页</button></nav>
<section v-if="annual&&data.related.length" class="related-stories"><h2>故事相连</h2><a v-for="r in data.related" :key="r.id+r.label" :href="'/posts/'+r.id" @click.prevent="emit('navigate','/posts/'+r.id)"><span>{{r.label}}</span><strong>{{r.title}} ↗</strong></a></section></section></template>
<style scoped>
.life-filters{display:flex;align-items:end;gap:20px;flex-wrap:wrap;margin-bottom:40px}.life-filters label{flex:1;min-width:170px;color:var(--reader-body-text,var(--ink))}.life-filters select{background:var(--reader-card-background,var(--surface));color:var(--reader-body-text,var(--ink));border-color:var(--reader-border,var(--line))}.life-filters button,.life-filters>a{margin-bottom:15px}.life-records{list-style:none;padding:0 0 0 25px;border-left:2px solid var(--reader-border,var(--line));margin:40px 0}.life-records li{padding:20px 25px;margin-bottom:25px;border:1px solid var(--reader-border,var(--line));border-radius:var(--radius);background:var(--reader-card-background,var(--surface));overflow-wrap:anywhere}.life-records time,.life-records span{font-size:13px;color:var(--reader-muted-text,var(--muted))}.life-records h2{font-size:clamp(24px,4vw,36px);margin:12px 0}.year-summary{margin:40px 0}.year-summary ul{display:flex;list-style:none;gap:15px;flex-wrap:wrap;padding:0}.year-summary li{padding:12px 20px;border:1px solid var(--reader-border,var(--line));border-radius:var(--radius)}.year-photo-links{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:18px}.year-photo-links a,.year-photo-links span{display:block;font-size:14px;overflow-wrap:anywhere}.year-photo-links a{min-height:44px}.life-feed{max-width:1050px;margin:auto}@media(max-width:600px){.life-filters{gap:8px}.life-filters label{min-width:100%}.life-records{padding-left:12px}.life-records li{padding:18px}}
</style>
